INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann ich als Informatikkaufmann IT-Projekte eigenständig planen?', 2, '[{"text": "Ja", "correct": true, "because": "Projektmanagement gehört dazu"}, {"text": "Nein", "correct": false, "because": "Planung ist Teil der Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Informatikkaufmann auch Netzwerke einrichten?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Kaufmännisches und IT"}, {"text": "Ja", "correct": false, "because": "Technik ist nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Verkauf von IT-Lösungen eine Aufgabe für Informatikkaufleute?', 2, '[{"text": "Ja", "correct": true, "because": "Kundenorientiertes Verkaufen ist Kern"}, {"text": "Nein", "correct": false, "because": "Verkauf gehört dazu"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich als Informatikkaufmann nur im Marketing arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Rolle umfasst mehr Bereiche"}, {"text": "Ja", "correct": false, "because": "Vielfalt der Aufgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Brauche ich IT-Kenntnisse als Informatikkaufmann?', 2, '[{"text": "Ja", "correct": true, "because": "Technisches Verständnis ist Pflicht"}, {"text": "Nein", "correct": false, "because": "Ohne IT schwer möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Informatikkaufmann auch Angebote für Software erstellen?', 2, '[{"text": "Ja", "correct": true, "because": "Angebotserstellung ist typisch"}, {"text": "Nein", "correct": false, "because": "Teil der Aufgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Kostenrechnung eine typische Tätigkeit für Informatikkaufleute?', 2, '[{"text": "Ja", "correct": true, "because": "Kaufmännische Aufgabe"}, {"text": "Nein", "correct": false, "because": "Wirtschaftlichkeit prüfen"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich als Informatikkaufmann ohne Kundenkontakt auskommen?', 2, '[{"text": "Nein", "correct": true, "because": "Kundenarbeit ist zentral"}, {"text": "Ja", "correct": false, "because": "Kontakt oft nötig"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe übernimmt ein Informatikkaufmann am häufigsten?', 2, '[{"text": "Kundenberatung", "correct": true, "because": "Kernaufgabe"}, {"text": "Serverwartung", "correct": false, "because": "Technische Rolle"}, {"text": "Code schreiben", "correct": false, "because": "Entwickleraufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin will, dass ich ein IT-Projekt koordiniere. Was ist mein erster Schritt?', 3, '[{"text": "Anforderungen sammeln", "correct": true, "because": "Basis für Planung"}, {"text": "Budget festlegen", "correct": false, "because": "Kommt später"}, {"text": "Hardware kaufen", "correct": false, "because": "Zu früh"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool nutzt ein Informatikkaufmann oft für Projektmanagement?', 2, '[{"text": "MS Project", "correct": true, "because": "Standard in der Branche"}, {"text": "Photoshop", "correct": false, "because": "Design-Tool"}, {"text": "Linux", "correct": false, "because": "Betriebssystem"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter sagte, ich soll eine IT-Lösung verkaufen. Was ist entscheidend?', 3, '[{"text": "Kundenbedarf verstehen", "correct": true, "because": "Basis für Erfolg"}, {"text": "Technische Details erklären", "correct": false, "because": "Zweitens"}, {"text": "Preis senken", "correct": false, "because": "Nicht primär"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welche Tätigkeiten gehören zum Informatikkaufmann?', 4, '[{"text": "Angebotserstellung", "correct": true, "because": "Kaufmännisch"}, {"text": "Kundenberatung", "correct": true, "because": "Verkauf"}, {"text": "Projektplanung", "correct": true, "because": "Koordination"}, {"text": "Netzwerkadministration", "correct": false, "because": "Technische Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Was braucht ein Informatikkaufmann für den Job?', 3, '[{"text": "Kommunikationsfähigkeit", "correct": true, "because": "Kundenkontakt"}, {"text": "IT-Grundkenntnisse", "correct": true, "because": "Technisches Verständnis"}, {"text": "Verhandlungsgeschick", "correct": true, "because": "Verkauf"}, {"text": "Programmierung", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wir müssen eine Software für einen Kunden auswählen. Was prüft ein Informatikkaufmann?', 3, '[{"text": "Kosten", "correct": true, "because": "Wirtschaftlichkeit"}, {"text": "Anforderungen", "correct": true, "because": "Kundenbedarf"}, {"text": "Vertragsdetails", "correct": true, "because": "Rechtliche Absicherung"}, {"text": "Serverleistung", "correct": false, "because": "Technische Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche deckt ein Informatikkaufmann ab?', 4, '[{"text": "Vertrieb", "correct": true, "because": "Verkauf"}, {"text": "Einkauf", "correct": true, "because": "Beschaffung"}, {"text": "Controlling", "correct": true, "because": "Kostenprüfung"}, {"text": "Hardware-Reparatur", "correct": false, "because": "Nicht primär"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Informatikkaufmann berät Kunden zu IT-Lösungen. b) Er muss Server konfigurieren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Beratung ja, Server nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Projektmanagement ist Teil des Jobs. b) Englischkenntnisse sind unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Management ja, Englisch hilft"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Informatikkaufmann kalkuliert IT-Projektkosten. b) Er entwickelt Apps.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kalkulation ja, Entwicklung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Informatikkaufmann arbeitet oft mit ERP-Systemen. b) Er braucht keine kaufmännischen Kenntnisse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ERP ja, Kaufmännisches nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

